"""Cart pricing."""

import re

from cart.models import Line, Totals

_BULK_MIN_QTY = 10
_BULK_PERCENT = 10
_PERCENT_RE = re.compile(r"PERCENT:([0-9]+)")
_FIXED_RE = re.compile(r"FIXED:([0-9]+)")


def _percent_of(amount: int, percent: int) -> int:
    """`percent` of `amount` in cents, rounded to the nearest cent with halves rounding up."""
    return (amount * percent + 50) // 100


def _parse_coupon(coupon: str) -> tuple[str, int]:
    percent_match = _PERCENT_RE.fullmatch(coupon)
    if percent_match:
        percent = int(percent_match.group(1))
        if not 1 <= percent <= 100:
            raise ValueError(f"percentage out of range 1..100: {percent}")
        return "PERCENT", percent
    fixed_match = _FIXED_RE.fullmatch(coupon)
    if fixed_match:
        return "FIXED", int(fixed_match.group(1))
    raise ValueError(f"unknown coupon: {coupon!r}")


def price_cart(lines: list[Line], coupon: str | None = None) -> Totals:
    """Price a cart. See README.md for the discount rules."""
    for line in lines:
        if line.qty < 1:
            raise ValueError(f"quantity below 1 for {line.sku!r}: {line.qty}")
        if line.unit_cents < 0:
            raise ValueError(f"negative unit price for {line.sku!r}: {line.unit_cents}")
    coupon_spec = _parse_coupon(coupon) if coupon is not None else None

    subtotal = 0
    bulk_discount = 0
    for line in lines:
        amount = line.unit_cents * line.qty
        subtotal += amount
        if line.qty >= _BULK_MIN_QTY:
            bulk_discount += _percent_of(amount, _BULK_PERCENT)

    remaining = subtotal - bulk_discount
    coupon_discount = 0
    if coupon_spec is not None:
        kind, value = coupon_spec
        if kind == "PERCENT":
            coupon_discount = _percent_of(remaining, value)
        else:
            coupon_discount = value
        coupon_discount = min(coupon_discount, remaining)

    discount = bulk_discount + coupon_discount
    return Totals(subtotal=subtotal, discount=discount, total=subtotal - discount)
